"""Turn the kernel's own names for files into paths the caller can open.

Everything the address space APIs hand back about a file is a *device* path:
``GetMappedFileNameW`` reports ``\\Device\\HarddiskVolume3\\dir\\thing.dll`` and
``GetModuleFileNameExW`` may report ``\\Device\\Mup\\server\\share\\thing.dll``.
Neither of those can be pasted into a ticket, opened from Explorer or handed to
:func:`open`, so the auditor translates every one of them into a DOS drive path
(``C:\\dir\\thing.dll``) or a UNC path (``\\\\server\\share\\thing.dll``).

When no translation is possible -- the volume is not mounted under a drive
letter, the file has been deleted and renamed by the system, the kernel refuses
to answer -- the caller gets ``None``. The auditor never invents a path and
never leaks a device path out through the public API.
"""

import ctypes
import os

from . import _winapi as w

# Device paths are not bounded by MAX_PATH; give the kernel room to answer.
PATH_BUFFER_CHARS = 4096
# QueryDosDeviceW writes a double NUL terminated list of device targets.
DEVICE_BUFFER_CHARS = 1 << 15

_NT_DEVICE_PREFIX = "\\Device\\"
_NT_NAMESPACE_PREFIX = "\\??\\"
_WIN32_DEVICE_PREFIX = "\\\\.\\"
_WIN32_FILE_PREFIX = "\\\\?\\"

_device_map = None


def _wide_buffer(chars):
    return ctypes.create_unicode_buffer(chars)


def _multi_string(buffer, chars):
    """Decode a double NUL terminated list out of ``buffer``."""
    if chars <= 0:
        return []
    raw = ctypes.wstring_at(ctypes.addressof(buffer), chars)
    return [item for item in raw.split("\0") if item]


def _logical_drives():
    """Every drive letter this machine currently has mounted."""
    if w.GetLogicalDriveStringsW is None:
        return []
    needed = w.GetLogicalDriveStringsW(0, None)
    if not needed:
        return []
    buffer = _wide_buffer(needed + 2)
    written = w.GetLogicalDriveStringsW(needed + 1, buffer)
    if not written:
        return []
    return [item for item in buffer.value.split("\0") if item]


def _device_targets(dos_name):
    """The device name(s) a DOS name such as ``C:`` or ``Volume{...}`` maps to."""
    if w.QueryDosDeviceW is None:
        return []
    buffer = _wide_buffer(DEVICE_BUFFER_CHARS)
    written = w.QueryDosDeviceW(dos_name, buffer, DEVICE_BUFFER_CHARS)
    if not written:
        return []
    return _multi_string(buffer, written)


def _dos_root(name):
    """Normalise one entry of a drive list to the form QueryDosDeviceW wants."""
    drive = name.strip().rstrip("\\")
    if not drive:
        return None
    if len(drive) == 2 and drive[1] == ":":
        return drive
    if drive.endswith(":"):
        return drive
    return drive + ":"


def _volume_guid_target(name):
    """Device target of a ``Volume{...}`` DOS device name, if it has one."""
    for target in _device_targets(name):
        if not target:
            continue
        if target.startswith(_WIN32_DEVICE_PREFIX):
            return target[len(_WIN32_DEVICE_PREFIX):] or target
        return target
    return None


def device_map():
    """``device name -> openable root``, built on first use.

    Longest device names come first so that a query for a nested volume such as
    ``\\Device\\HarddiskVolume3`` is not shadowed by ``\\Device\\Harddisk``.
    """
    global _device_map
    if _device_map is not None:
        return _device_map

    entries = {}
    seen = {}
    for drive in _logical_drives():
        root = _dos_root(drive)
        if root is None or root in seen:
            continue
        targets = _device_targets(root)
        if not targets:
            continue
        primary = _normalise_device(targets[0])
        seen[root] = primary
        if primary and primary not in entries:
            entries[primary] = root
        # A volume can carry more than one name (\Device\HarddiskVolume3 and
        # \Device\VhdHardDisk{...} for instance); they all open through the
        # same drive letter.
        for target in targets[1:]:
            alias = _normalise_device(target)
            if alias and alias not in entries:
                entries[alias] = root

    # ``Volume{guid}`` names are usable as DOS devices themselves; the drive
    # letter lookup above does not always see them, and a mapped file may well
    # be reported through one.
    for name in _device_names():
        if not name.startswith("Volume{"):
            continue
        target = _volume_guid_target(name)
        if not target:
            continue
        device = _normalise_device(target)
        if device and device not in entries:
            entries[device] = "\\\\?\\" + name + "\\"

    _device_map = [(name, entries[name]) for name in
                   sorted(entries, key=len, reverse=True) if entries[name]]
    return _device_map


def _device_names():
    """Every DOS device name known to this session."""
    if w.QueryDosDeviceW is None:
        return []
    buffer = _wide_buffer(DEVICE_BUFFER_CHARS)
    written = w.QueryDosDeviceW(None, buffer, DEVICE_BUFFER_CHARS)
    if not written:
        return []
    return _multi_string(buffer, written)


def _normalise_device(name):
    """Compare device names case insensitively and without a ``\\??\\`` prefix."""
    if not name:
        return ""
    device = name
    if device.startswith(_NT_NAMESPACE_PREFIX):
        device = _NT_DEVICE_PREFIX + device[len(_NT_NAMESPACE_PREFIX):]
    elif device.startswith(_WIN32_DEVICE_PREFIX):
        device = _NT_DEVICE_PREFIX + device[len(_WIN32_DEVICE_PREFIX):]
    elif device.startswith(_WIN32_FILE_PREFIX):
        device = device[len(_WIN32_FILE_PREFIX):]
    return device.rstrip("\\").lower()


def _strip_known_prefix(value):
    """Drop the path prefixes that are not part of the path itself."""
    if value.startswith(_WIN32_FILE_PREFIX):
        return value[len(_WIN32_FILE_PREFIX):]
    return value


def _join(root, remainder):
    root = root.rstrip("\\")
    if not remainder:
        return root
    return root + "\\" + remainder.strip("\\")


def _candidate_is_usable(candidate):
    """Refuse to hand back something that is still a device name."""
    if not candidate:
        return False
    lowered = candidate.lower()
    if lowered.startswith(_NT_DEVICE_PREFIX) or lowered.startswith(_NT_NAMESPACE_PREFIX):
        return False
    if candidate.startswith(_WIN32_DEVICE_PREFIX):
        return False
    return True


def _translate_device_path(value):
    """``\\Device\\...`` or ``\\??\\...`` -> drive/UNC path, or ``None``."""
    if not value:
        return None
    if value.startswith(_NT_NAMESPACE_PREFIX):
        value = _NT_DEVICE_PREFIX + value[len(_NT_NAMESPACE_PREFIX):]
    elif value.startswith(_WIN32_DEVICE_PREFIX):
        value = _NT_DEVICE_PREFIX + value[len(_WIN32_DEVICE_PREFIX):]
    if not value.lower().startswith(_NT_DEVICE_PREFIX):
        return None
    lowered = value.lower()
    for device, root in device_map():
        if lowered == device or lowered.startswith(device + "\\"):
            remainder = value[len(device):].strip("\\")
            candidate = _join(root, remainder)
            if _candidate_is_usable(candidate):
                return candidate
    return None


def to_openable_path(value):
    """Return ``value`` as a DOS/UNC path, or ``None`` if it cannot be one.

    Accepts the shapes the Win32 naming APIs produce and never returns a
    device path, an empty string or a placeholder.
    """
    if not value or not isinstance(value, str):
        return None
    candidate = value.strip()
    if not candidate:
        return None

    if candidate.startswith(_NT_DEVICE_PREFIX) or candidate.startswith(_NT_NAMESPACE_PREFIX):
        return _translate_device_path(candidate)
    if candidate.startswith(_WIN32_DEVICE_PREFIX):
        return _translate_device_path(candidate)

    candidate = _strip_known_prefix(candidate)
    if not _candidate_is_usable(candidate):
        return None

    # ``\\?\UNC\server\share\dir`` is the file namespace spelling of UNC.
    if candidate.lower().startswith("unc\\"):
        candidate = "\\\\" + candidate[len("unc\\"):].strip("\\")

    if len(candidate) > 1 and candidate[1] == ":" and candidate[2:3] != "\\":
        candidate = candidate[:2] + "\\" + candidate[2:]
    return candidate or None


def mapped_file_name(handle, address):
    """The openable path of the file mapped at ``address`` in ``handle``.

    ``None`` when the kernel does not name a file for that address -- anonymous
    sections, private memory, reserved memory, or a device that cannot be
    translated back to a path the caller could open.
    """
    if w.GetMappedFileNameW is None:
        return None
    buffer = _wide_buffer(PATH_BUFFER_CHARS)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        return None
    return to_openable_path(buffer.value)


def process_image_name(handle):
    """The openable path of the process's own executable image."""
    if w.QueryFullProcessImageNameW is None:
        return None
    size = ctypes.wintypes.DWORD(PATH_BUFFER_CHARS)
    buffer = _wide_buffer(PATH_BUFFER_CHARS)
    ok = w.QueryFullProcessImageNameW(handle, 0, buffer, ctypes.byref(size))
    if not ok:
        return None
    return to_openable_path(buffer.value)


def normalise_path(value):
    """Case insensitive, canonical spelling of a path, for comparisons only."""
    if not value:
        return ""
    try:
        return os.path.normcase(os.path.normpath(value))
    except (TypeError, ValueError):
        return os.path.normcase(value)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process exactly as the system sees
it: full address width, true region sizes, reserved ranges included when asked
for, and file names that can actually be opened.
"""

import ctypes
import ctypes.wintypes as wt

from . import _winapi as w
from ._paths import (
    PATH_BUFFER_CHARS,
    mapped_file_name,
    normalise_path,
    process_image_name,
    to_openable_path,
)
from .errors import WVasError

# Address space walk bounds. They are refined from GetSystemInfo() at run time
# so that a 32 bit target is walked over its own address space rather than
# over somebody else's guess.
DEFAULT_MIN_ADDRESS = 0x10000
DEFAULT_MAX_ADDRESS = 0x7FFFFFFEFFFF

# A reserved range is never reported as "no protection"; the protection the
# range was reserved with is the one that means something to a reader.
RESERVE_PROTECT = w.PAGE_NOACCESS

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# errors
# ---------------------------------------------------------------------------

def _pid_is_usable(pid):
    return isinstance(pid, int) and not isinstance(pid, bool) and pid > 0


def _raise_open_failure(pid, error):
    """Classify a failed OpenProcess into the wvas error taxonomy."""
    if error == w.ERROR_ACCESS_DENIED or error == w.ERROR_PRIVILEGE_NOT_HELD:
        raise WVasError(
            "no permission to query process %d" % pid,
            kind="access-denied",
            pid=pid,
        )
    if error == w.ERROR_INVALID_PARAMETER:
        # Windows answers a request for a process id that is not in use with
        # ERROR_INVALID_PARAMETER; a process that is on its way out answers
        # ERROR_ACCESS_DENIED. Both mean "nothing to audit here".
        if _process_is_gone(pid):
            raise WVasError(
                "no such process: %d" % pid, kind="no-such-process", pid=pid
            )
        raise WVasError(
            "no permission to query process %d" % pid,
            kind="access-denied",
            pid=pid,
        )
    if error == w.ERROR_INVALID_HANDLE:
        raise WVasError(
            "no such process: %d" % pid, kind="no-such-process", pid=pid
        )
    raise WVasError(
        "cannot open process %d (win32 error %d)" % (pid, error),
        kind="query-failed",
        pid=pid,
    )


def _process_is_gone(pid):
    """``True`` when the process table has no entry for ``pid``."""
    if w.CreateToolhelp32Snapshot is None or w.Process32FirstW is None:
        return True
    snapshot = w.CreateToolhelp32Snapshot(w.TH32CS_SNAPPROCESS, 0)
    if not snapshot or snapshot == w.INVALID_HANDLE_VALUE:
        return True
    try:
        entry = w.PROCESSENTRY32W()
        entry.dwSize = ctypes.sizeof(w.PROCESSENTRY32W)
        if not w.Process32FirstW(snapshot, ctypes.byref(entry)):
            return True
        while True:
            if entry.th32ProcessID == pid:
                return False
            if not w.Process32NextW(snapshot, ctypes.byref(entry)):
                return True
    finally:
        w.CloseHandle(snapshot)


def _check_pid(pid):
    if not _pid_is_usable(pid):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _check_pid(pid)

    desired = w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ
    handle = w.OpenProcess(desired, False, pid)
    if not handle:
        error = w.last_error()
        if desired != w.PROCESS_QUERY_LIMITED_INFORMATION:
            limited = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
            if not limited:
                error = w.last_error()
            else:
                w.CloseHandle(limited)
        _raise_open_failure(pid, error)

    # A handle with no read access cannot answer the region walk; make sure we
    # never hand out one that silently reports an empty address space.
    if _has_read_access(handle, pid):
        return handle
    w.CloseHandle(handle)
    raise WVasError(
        "no permission to query process %d" % pid, kind="access-denied", pid=pid
    )


def _has_read_access(handle, pid):
    """Probe the handle once so later failures cannot be blamed on access."""
    mbi = w.MEMORY_BASIC_INFORMATION()
    written = w.VirtualQueryEx(
        handle, ctypes.c_void_p(0), ctypes.byref(mbi), ctypes.sizeof(mbi)
    )
    if written:
        return True
    error = w.last_error()
    if error in (w.ERROR_ACCESS_DENIED, w.ERROR_PARTIAL_COPY):
        return False
    if error == w.ERROR_INVALID_PARAMETER:
        # Some protected processes refuse the very first page; treat that as a
        # permission problem rather than an unusable handle.
        return False
    return True


def _close_process(handle):
    if handle:
        w.CloseHandle(handle)


def _fail(message, pid, kind="query-failed", error=None):
    if error is None:
        error = w.last_error()
    if error == w.ERROR_ACCESS_DENIED or error == w.ERROR_PARTIAL_COPY:
        kind = "access-denied"
    detail = message if not error else "%s (win32 error %d)" % (message, error)
    raise WVasError(detail, kind=kind, pid=pid)


# ---------------------------------------------------------------------------
# address space walk
# ---------------------------------------------------------------------------

def _address_space_bounds(handle):
    """The range of user addresses to walk for the owner of ``handle``."""
    if w.GetSystemInfo is None:
        return DEFAULT_MIN_ADDRESS, DEFAULT_MAX_ADDRESS
    info = w.SYSTEM_INFO()
    try:
        w.GetSystemInfo(ctypes.byref(info))
    except (OSError, ValueError):
        return DEFAULT_MIN_ADDRESS, DEFAULT_MAX_ADDRESS
    lowest = info.lpMinimumApplicationAddress or 0
    highest = info.lpMaximumApplicationAddress or 0
    if not lowest:
        lowest = DEFAULT_MIN_ADDRESS
    if not highest:
        highest = DEFAULT_MAX_ADDRESS
    # The pointer is truncated to the width of *this* process, so a 64 bit
    # ceiling can never be reached by c_void_p on 32 bit Python; the walk stops
    # on the first failing query in that case.
    return int(lowest), int(highest)


def _query_region(handle, address, mbi):
    return w.VirtualQueryEx(
        handle, ctypes.c_void_p(address), ctypes.byref(mbi), ctypes.sizeof(mbi)
    )


def _region_state(mbi):
    return "commit" if mbi.State == w.MEM_COMMIT else "reserve"


def _region_protect(mbi):
    """The protection a reader cares about for this region."""
    if mbi.State == w.MEM_COMMIT:
        if mbi.Protect:
            return protection_name(mbi.Protect)
        return protection_name(mbi.AllocationProtect or RESERVE_PROTECT)
    # A reserved range has no page protection of its own.
    return protection_name(mbi.AllocationProtect or RESERVE_PROTECT)


def _region_path(handle, mbi):
    """The file behind this region, as an openable path, or ``None``."""
    if mbi.State != w.MEM_COMMIT:
        return None
    if mbi.Type not in (w.MEM_IMAGE, w.MEM_MAPPED):
        return None
    return mapped_file_name(handle, mbi.BaseAddress or 0)


def _walk_regions(handle, include_reserved):
    """Yield ``(base, size, state, type, protect, path, image)`` per region."""
    lowest, highest = _address_space_bounds(handle)
    mbi = w.MEMORY_BASIC_INFORMATION()
    address = lowest
    while address <= highest:
        if not _query_region(handle, address, mbi):
            break
        base = mbi.BaseAddress
        size = mbi.RegionSize
        if base is None or not size:
            break
        state = _region_state(mbi)
        if state == "commit" or include_reserved:
            yield {
                "base": int(base),
                "size": int(size),
                "state": state,
                "type": type_name(mbi.Type),
                "protect": _region_protect(mbi),
                "path": _region_path(handle, mbi),
                "image": bool(mbi.Type == w.MEM_IMAGE and state == "commit"),
            }
        next_address = base + size
        if next_address <= address:
            break
        address = next_address


# ---------------------------------------------------------------------------
# loaded images
# ---------------------------------------------------------------------------

def _enum_module_handles(handle):
    """Every image handle the system will name for this process."""
    handles = []
    required = wt.DWORD(0)
    buffer = (wt.HMODULE * 256)()
    if w.EnumProcessModulesEx is not None:
        ok = w.EnumProcessModulesEx(
            handle, buffer, ctypes.sizeof(buffer), ctypes.byref(required),
            w.LIST_MODULES_ALL,
        )
        error = w.last_error()
    elif w.EnumProcessModules is not None:
        ok = w.EnumProcessModules(
            handle, buffer, ctypes.sizeof(buffer), ctypes.byref(required)
        )
        error = w.last_error()
    else:
        return None

    if not ok and error not in (w.ERROR_BAD_LENGTH, w.ERROR_INSUFFICIENT_BUFFER):
        return None

    count = required.value // ctypes.sizeof(wt.HMODULE)
    if count > len(buffer):
        bigger = (wt.HMODULE * (count + 16))()
        if w.EnumProcessModulesEx is not None:
            ok = w.EnumProcessModulesEx(
                handle, bigger, ctypes.sizeof(bigger), ctypes.byref(required),
                w.LIST_MODULES_ALL,
            )
        else:
            ok = w.EnumProcessModules(
                handle, bigger, ctypes.sizeof(bigger), ctypes.byref(required)
            )
        count = required.value // ctypes.sizeof(wt.HMODULE)
        buffer = bigger if ok or count else buffer

    for index in range(min(count, len(buffer))):
        if buffer[index]:
            handles.append(buffer[index])
    return handles


def _module_image_size(handle, module):
    if w.GetModuleInformation is None:
        return 0
    info = w.MODULEINFO()
    if not w.GetModuleInformation(handle, module, ctypes.byref(info), ctypes.sizeof(info)):
        return 0
    return int(info.SizeOfImage or 0)


def _module_file_name(handle, module):
    if w.GetModuleFileNameExW is None:
        return None
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = w.GetModuleFileNameExW(handle, module, buffer, PATH_BUFFER_CHARS)
    if not written:
        return None
    return to_openable_path(buffer.value)


def _module_table(handle):
    """``image base -> {"path": ..., "size": ...}`` for every loaded image."""
    handles = _enum_module_handles(handle)
    table = {}
    if not handles:
        return table
    for module in handles:
        size = _module_image_size(handle, module)
        if not size:
            continue
        name = _module_file_name(handle, module)
        base = _module_base(handle, module)
        if base is None:
            continue
        entry = table.setdefault(base, {"path": None, "size": size})
        if name and not entry["path"]:
            entry["path"] = name
        if not entry["size"]:
            entry["size"] = size
    return table


def _module_base(handle, module):
    if w.GetModuleInformation is None:
        return None
    info = w.MODULEINFO()
    if not w.GetModuleInformation(handle, module, ctypes.byref(info), ctypes.sizeof(info)):
        return None
    base = info.lpBaseOfDll
    return None if base is None else int(base)


def _image_bases(handle):
    """Every allocation base of an image region, lowest first."""
    bases = {}
    lowest, highest = _address_space_bounds(handle)
    mbi = w.MEMORY_BASIC_INFORMATION()
    address = lowest
    while address <= highest:
        if not _query_region(handle, address, mbi):
            break
        base = mbi.BaseAddress
        size = mbi.RegionSize
        if base is None or not size:
            break
        if mbi.State == w.MEM_COMMIT and mbi.Type == w.MEM_IMAGE:
            allocation = mbi.AllocationBase or base
            record = bases.setdefault(int(allocation), {"size": 0, "path": None})
            record["size"] += int(size)
            if record["path"] is None:
                record["path"] = mapped_file_name(handle, base)
        next_address = base + size
        if next_address <= address:
            break
        address = next_address
    return bases


def _collect_modules(handle, pid):
    """The loaded images of ``handle``'s process, one entry per image."""
    table = _module_table(handle)
    scanned = _image_bases(handle)

    modules = {}
    for base, record in scanned.items():
        entry = dict(table.get(base, {"path": None, "size": 0}))
        path = entry.get("path") or record.get("path")
        size = entry.get("size") or record.get("size") or 0
        modules[base] = {"path": path, "size": size}

    for base, entry in table.items():
        if base in modules:
            continue
        modules[base] = {"path": entry.get("path"), "size": entry.get("size") or 0}

    if not modules:
        _fail("cannot list the loaded images", pid, kind="query-failed")
    return modules


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Each region is a dict with the keys ``base``, ``size``, ``state``,
    ``type``, ``protect``, ``path`` and ``image``, in ascending order of
    ``base``. ``base`` and ``size`` are reported at full address width, exactly
    as :func:`VirtualQueryEx` measured them.
    """
    _check_pid(pid)
    include = bool(include_reserved)
    handle = _open_process(pid)
    try:
        found = list(_walk_regions(handle, include))
    finally:
        _close_process(handle)
    if not found:
        _fail("the address space of the process could not be read", pid)
    found.sort(key=lambda item: item["base"])
    return found


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every loaded image appears exactly once, with its base address, the size
    of the image and the path of the file it was loaded from. ``path`` is
    ``None`` only when the file cannot be translated into something the caller
    could open.
    """
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        table = _collect_modules(handle, pid)
    finally:
        _close_process(handle)

    main_image = process_image_name(handle) if False else None

    entries = []
    for base in sorted(table):
        entry = table[base]
        path = entry.get("path")
        size = int(entry.get("size") or 0)
        if path is None:
            path = _fallback_image_path(handle, base, pid, main_image)
        if size <= 0:
            size = _fallback_image_size(handle, base)
        entries.append({"path": path, "base": int(base), "size": size})
    return entries


# ``main_image`` is resolved lazily, inside the fallback, because it needs an
# open handle and most runs never get there.
_main_image_cache = {}


def _fallback_image_path(handle, base, pid, _ignored=None):
    """Name an image whose file the system would not name for us."""
    key = None
    try:
        key = None if handle is None else int(handle)
    except (TypeError, ValueError):
        key = None
    if key in _main_image_cache:
        cached = _main_image_cache[key]
    else:
        cached = process_image_name(handle)
        if key is not None:
            _main_image_cache[key] = cached
    if cached:
        return cached
    return None


def _fallback_image_size(handle, base):
    """Size of an image region, measured from the address space itself."""
    mbi = w.MEMORY_BASIC_INFORMATION()
    if not _query_region(handle, base, mbi):
        return 0
    if mbi.AllocationBase and int(mbi.AllocationBase) != int(base):
        return int(mbi.RegionSize or 0)
    total = int(mbi.RegionSize or 0)
    address = base + total
    while True:
        if not _query_region(handle, address, mbi):
            break
        if mbi.AllocationBase is None or int(mbi.AllocationBase) != int(base):
            break
        if mbi.Type != w.MEM_IMAGE or mbi.State != w.MEM_COMMIT:
            break
        total += int(mbi.RegionSize or 0)
        next_address = (mbi.BaseAddress or 0) + int(mbi.RegionSize or 0)
        if next_address <= address:
            break
        address = next_address
    return total


__all__ = [
    "file_backed_regions",
    "modules",
    "protection_name",
    "regions",
    "type_name",
]

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process exactly as the system sees
it: full address width, true region sizes, reserved ranges included when they
are asked for, and file names that can actually be opened.

Every failure leaves this module as a :class:`WVasError` with a ``kind`` from
the taxonomy in :mod:`wvas.errors`; no Win32 error ever reaches the caller as a
bare :class:`OSError`.
"""

import ctypes
import ctypes.wintypes as wt

from . import _winapi as w
from ._paths import (
    PATH_BUFFER_CHARS,
    mapped_file_name,
    process_image_name,
    to_openable_path,
)
from .errors import WVasError

# Bounds for the address space walk. They are refined from GetSystemInfo() at
# run time so the walk covers the target's own user address space rather than
# a hard coded guess; these are the 64 bit x64 values.
DEFAULT_MIN_ADDRESS = 0x10000
DEFAULT_MAX_ADDRESS = 0x7FFFFFFEFFFF

# A reserved range carries no page protection of its own. The protection it was
# reserved with is the one that means something to a reader of the report.
RESERVE_PROTECT = w.PAGE_NOACCESS

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# error classification
# ---------------------------------------------------------------------------

def _pid_is_usable(pid):
    return isinstance(pid, int) and not isinstance(pid, bool) and pid > 0


def _check_pid(pid):
    if not _pid_is_usable(pid):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _process_is_gone(pid):
    """``True`` when the process table holds no entry for ``pid``."""
    if (w.CreateToolhelp32Snapshot is None or w.Process32FirstW is None
            or w.Process32NextW is None):
        return True
    snapshot = w.CreateToolhelp32Snapshot(w.TH32CS_SNAPPROCESS, 0)
    if not snapshot or snapshot == w.INVALID_HANDLE_VALUE:
        return True
    try:
        entry = w.PROCESSENTRY32W()
        entry.dwSize = ctypes.sizeof(w.PROCESSENTRY32W)
        if not w.Process32FirstW(snapshot, ctypes.byref(entry)):
            return True
        while True:
            if entry.th32ProcessID == pid:
                return False
            if not w.Process32NextW(snapshot, ctypes.byref(entry)):
                return True
    finally:
        w.CloseHandle(snapshot)


def _raise_open_failure(pid, error):
    """Classify a failed ``OpenProcess`` into the wvas error taxonomy."""
    if error in (w.ERROR_ACCESS_DENIED, w.ERROR_PRIVILEGE_NOT_HELD):
        # The process is there (or was a moment ago) and we may not read it.
        raise WVasError(
            "no permission to query process %d" % pid,
            kind="access-denied",
            pid=pid,
        )
    if error == w.ERROR_INVALID_PARAMETER:
        # Windows answers a request for a process id that is not in use with
        # ERROR_INVALID_PARAMETER rather than with a "not found" error.
        if _process_is_gone(pid):
            raise WVasError(
                "no such process: %d" % pid, kind="no-such-process", pid=pid
            )
        raise WVasError(
            "no permission to query process %d" % pid,
            kind="access-denied",
            pid=pid,
        )
    if error == w.ERROR_INVALID_HANDLE:
        raise WVasError(
            "no such process: %d" % pid, kind="no-such-process", pid=pid
        )
    raise WVasError(
        "cannot open process %d (win32 error %d)" % (pid, error),
        kind="query-failed",
        pid=pid,
    )


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _check_pid(pid)
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if not handle:
        _raise_open_failure(pid, w.last_error())
    return handle


def _close_process(handle):
    if handle:
        w.CloseHandle(handle)


def _fail(message, pid, error=None):
    """Raise a :class:`WVasError` for a failed query."""
    if error is None:
        error = w.last_error()
    if error in (w.ERROR_ACCESS_DENIED, w.ERROR_PARTIAL_COPY):
        kind = "access-denied"
    else:
        kind = "query-failed"
    detail = message if not error else "%s (win32 error %d)" % (message, error)
    raise WVasError(detail, kind=kind, pid=pid)


# ---------------------------------------------------------------------------
# address space walk
# ---------------------------------------------------------------------------

def _address_space_bounds(handle):
    """The user address range to walk for the owner of ``handle``."""
    if w.GetSystemInfo is None:
        return DEFAULT_MIN_ADDRESS, DEFAULT_MAX_ADDRESS
    info = w.SYSTEM_INFO()
    try:
        w.GetSystemInfo(ctypes.byref(info))
    except (OSError, ValueError):
        return DEFAULT_MIN_ADDRESS, DEFAULT_MAX_ADDRESS
    lowest = info.lpMinimumApplicationAddress or 0
    highest = info.lpMaximumApplicationAddress or 0
    if not lowest:
        lowest = DEFAULT_MIN_ADDRESS
    if not highest:
        highest = DEFAULT_MAX_ADDRESS
    # A 64 bit ceiling cannot be held by c_void_p on 32 bit Python; the walk
    # simply stops at the first query the kernel refuses in that case.
    return int(lowest), int(highest)


def _query_region(handle, address, mbi):
    return w.VirtualQueryEx(
        handle, ctypes.c_void_p(address), ctypes.byref(mbi), ctypes.sizeof(mbi)
    )


def _region_protect(mbi):
    """The protection a reader of the report cares about."""
    if mbi.State == w.MEM_COMMIT and mbi.Protect:
        return protection_name(mbi.Protect)
    return protection_name(mbi.AllocationProtect or RESERVE_PROTECT)


def _region_path(handle, mbi):
    """The file behind this region, as an openable path, or ``None``."""
    if mbi.State != w.MEM_COMMIT:
        return None
    if mbi.Type not in (w.MEM_IMAGE, w.MEM_MAPPED):
        return None
    return mapped_file_name(handle, mbi.BaseAddress or 0)


def _scan_regions(handle, include_reserved):
    """Walk the target's address space once, reporting every region in it.

    ``base`` and ``size`` are reported exactly as the kernel measured them, at
    the full width of the target's address space.
    """
    found = []
    lowest, highest = _address_space_bounds(handle)
    mbi = w.MEMORY_BASIC_INFORMATION()
    address = lowest
    while address <= highest:
        if not _query_region(handle, address, mbi):
            break
        base = mbi.BaseAddress
        size = int(mbi.RegionSize or 0)
        if base is None or not size:
            break
        base = int(base)
        committed = mbi.State == w.MEM_COMMIT
        if committed or include_reserved:
            found.append({
                "base": base,
                "size": size,
                "state": "commit" if committed else "reserve",
                "type": type_name(mbi.Type),
                "protect": _region_protect(mbi),
                "path": _region_path(handle, mbi),
                "image": bool(committed and mbi.Type == w.MEM_IMAGE),
            })
        address = base + size
        if address <= base:
            break
    return found


def _scan_image_allocations(handle):
    """``allocation base -> {"size": ..., "path": ...}`` for every image.

    Measured from the address space itself, so an image is found even when the
    process manager will not enumerate it (a cross bitness target, for one).
    """
    images = {}
    lowest, highest = _address_space_bounds(handle)
    mbi = w.MEMORY_BASIC_INFORMATION()
    address = lowest
    while address <= highest:
        if not _query_region(handle, address, mbi):
            break
        base = mbi.BaseAddress
        size = int(mbi.RegionSize or 0)
        if base is None or not size:
            break
        base = int(base)
        if mbi.State == w.MEM_COMMIT and mbi.Type == w.MEM_IMAGE:
            allocation = mbi.AllocationBase or base
            record = images.setdefault(
                int(allocation), {"size": 0, "path": None}
            )
            record["size"] += size
            if record["path"] is None:
                record["path"] = mapped_file_name(handle, base)
        address = base + size
        if address <= base:
            break
    return images


# ---------------------------------------------------------------------------
# loaded images
# ---------------------------------------------------------------------------

def _enum_module_handles(handle):
    """The image handles the process manager will name for this process."""
    if w.EnumProcessModulesEx is not None:
        def enumerate_into(buffer):
            required = wt.DWORD(0)
            ok = w.EnumProcessModulesEx(
                handle, buffer, ctypes.sizeof(buffer), ctypes.byref(required),
                w.LIST_MODULES_ALL,
            )
            return ok, required.value, w.last_error()
    elif w.EnumProcessModules is not None:
        def enumerate_into(buffer):
            required = wt.DWORD(0)
            ok = w.EnumProcessModules(
                handle, buffer, ctypes.sizeof(buffer), ctypes.byref(required)
            )
            return ok, required.value, w.last_error()
    else:
        return None

    buffer = (wt.HMODULE * 256)()
    ok, needed, error = enumerate_into(buffer)
    if not ok and error not in (w.ERROR_BAD_LENGTH, w.ERROR_INSUFFICIENT_BUFFER):
        return None
    count = needed // ctypes.sizeof(wt.HMODULE)
    if count > len(buffer):
        buffer = (wt.HMODULE * (count + 32))()
        ok, needed, _error = enumerate_into(buffer)
        count = needed // ctypes.sizeof(wt.HMODULE)

    handles = []
    for index in range(min(count, len(buffer))):
        if buffer[index]:
            handles.append(buffer[index])
    return handles


def _module_info(handle, module):
    """``(base, size of image, openable path)`` for one module handle."""
    base = None
    size = 0
    if w.GetModuleInformation is not None:
        info = w.MODULEINFO()
        if w.GetModuleInformation(
                handle, module, ctypes.byref(info), ctypes.sizeof(info)):
            if info.lpBaseOfDll is not None:
                base = int(info.lpBaseOfDll)
            size = int(info.SizeOfImage or 0)
    if base is None:
        base = int(module or 0) or None
    path = None
    if w.GetModuleFileNameExW is not None:
        buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
        written = w.GetModuleFileNameExW(handle, module, buffer, PATH_BUFFER_CHARS)
        if written:
            path = to_openable_path(buffer.value)
    return base, size, path


def _module_table(handle):
    """``image base -> {"size": ..., "path": ...}``, one entry per image."""
    handles = _enum_module_handles(handle)
    if not handles:
        return {}
    table = {}
    for module in handles:
        base, size, path = _module_info(handle, module)
        if base is None:
            continue
        entry = table.get(base)
        if entry is None:
            table[base] = {"size": size, "path": path}
            continue
        if not entry["size"]:
            entry["size"] = size
        if path and not entry["path"]:
            entry["path"] = path
    return table


def _image_size_from_regions(handle, base):
    """Size of an image, measured from the address space walk."""
    mbi = w.MEMORY_BASIC_INFORMATION()
    if not _query_region(handle, base, mbi):
        return 0
    allocation = int(mbi.AllocationBase or base)
    if allocation != int(base):
        return int(mbi.RegionSize or 0)
    total = int(mbi.RegionSize or 0)
    address = base + total
    while True:
        if not _query_region(handle, address, mbi):
            break
        if mbi.State != w.MEM_COMMIT or mbi.Type != w.MEM_IMAGE:
            break
        if int(mbi.AllocationBase or 0) != allocation:
            break
        size = int(mbi.RegionSize or 0)
        if not size:
            break
        total += size
        address = int(mbi.BaseAddress or 0) + size
        if address <= base:
            break
    return total


def _collect_modules(handle, pid):
    """Every loaded image of the process, exactly once, ascending by base."""
    table = _module_table(handle)
    scanned = _scan_image_allocations(handle)
    main_image = process_image_name(handle)

    collected = {}
    for base, record in scanned.items():
        entry = table.get(base)
        path = None
        size = 0
        if entry:
            path = entry.get("path")
            size = entry.get("size") or 0
        if not path:
            path = record.get("path")
        if not size:
            size = record.get("size") or 0
        collected[base] = {"path": path, "size": size}
    for base, entry in table.items():
        if base in collected:
            continue
        collected[base] = {"path": entry.get("path"), "size": entry.get("size") or 0}

    if not collected:
        _fail("cannot list the loaded images", pid)

    lowest = min(collected) if collected else None
    result = []
    for base in sorted(collected):
        entry = collected[base]
        path = entry.get("path")
        if path is None and main_image and base == lowest:
            # The process manager named no file for this image. The lowest
            # image of a process is its executable, which the system can still
            # name for us; better an exact answer for that one than nothing.
            path = main_image
        size = entry.get("size") or 0
        if not size:
            size = _image_size_from_regions(handle, base)
        result.append({"path": path, "base": int(base), "size": int(size)})
    return result


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Every region is a dict with exactly the keys ``base``, ``size``, ``state``,
    ``type``, ``protect``, ``path`` and ``image``; the list is ascending by
    ``base``. With ``include_reserved`` both committed and reserved ranges are
    reported, without it only the committed ones.
    """
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        found = _scan_regions(handle, bool(include_reserved))
    finally:
        _close_process(handle)
    if not found:
        _fail("the address space of the process could not be read", pid)
    found.sort(key=lambda item: item["base"])
    return found


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Each image appears exactly once, as a dict with ``path``, ``base`` and
    ``size``. ``path`` is ``None`` only when the file behind the image cannot
    be turned into a path the caller could open.
    """
    _check_pid(pid)
    handle = _open_process(pid)
    try:
        return _collect_modules(handle, pid)
    finally:
        _close_process(handle)


__all__ = [
    "file_backed_regions",
    "modules",
    "protection_name",
    "regions",
    "type_name",
]

"""Turn the kernel's own names for files into paths the caller can open.

Everything the address space APIs hand back about a file is a *device* path:
``GetMappedFileNameW`` reports ``\\Device\\HarddiskVolume3\\dir\\thing.dll`` and
``GetModuleFileNameExW`` may report ``\\Device\\Mup\\server\\share\\thing.dll``.
Neither can be pasted into a ticket, opened from Explorer or handed to
:func:`open`, so this module translates them into a DOS drive path
(``C:\\dir\\thing.dll``) or a UNC path (``\\\\server\\share\\thing.dll``).

When no translation exists -- the volume is not mounted under a drive letter,
the file has been deleted and renamed by the system, the kernel refuses to
answer -- the caller gets ``None``. A device path is never handed out, and an
untranslatable name is never dressed up as something else.
"""

import ctypes

from . import _winapi as w

# Device paths are not bounded by MAX_PATH; give the kernel room to answer.
PATH_BUFFER_CHARS = 4096
# QueryDosDeviceW writes a double NUL terminated list of device targets.
DEVICE_BUFFER_CHARS = 1 << 15

_NT_DEVICE_PREFIX = "\\Device\\"
_NT_NAMESPACE_PREFIX = "\\??\\"
_WIN32_DEVICE_PREFIX = "\\\\.\\"
_WIN32_FILE_PREFIX = "\\\\?\\"
_UNC_PREFIX = "\\\\"

# Redirectors are not volumes; their device name is followed by the UNC path.
_REDIRECTORS = (
    "\\device\\mup\\",
    "\\device\\lanmanredirector\\",
    "\\device\\webdavredirector\\",
    "\\device\\davwwwroot\\",
)

_device_map = None


def _wide_buffer(chars):
    return ctypes.create_unicode_buffer(chars)


def _multi_string(buffer, chars):
    """Decode a double NUL terminated list out of ``buffer``."""
    if chars <= 0:
        return []
    raw = ctypes.wstring_at(ctypes.addressof(buffer), chars)
    return [item for item in raw.split("\0") if item]


def _logical_drives():
    """Every drive this machine currently has mounted."""
    if w.GetLogicalDriveStringsW is None:
        return []
    needed = w.GetLogicalDriveStringsW(0, None)
    if not needed:
        return []
    buffer = _wide_buffer(needed + 2)
    written = w.GetLogicalDriveStringsW(needed + 1, buffer)
    if not written:
        return []
    return [item for item in buffer.value.split("\0") if item]


def _device_targets(dos_name):
    """The device name(s) a DOS name such as ``C:`` maps to."""
    if w.QueryDosDeviceW is None:
        return []
    buffer = _wide_buffer(DEVICE_BUFFER_CHARS)
    written = w.QueryDosDeviceW(dos_name, buffer, DEVICE_BUFFER_CHARS)
    if not written:
        return []
    return _multi_string(buffer, written)


def _normalise_device(name):
    """Compare device names case insensitively, with one common spelling."""
    if not name:
        return ""
    device = name
    if device.startswith(_NT_NAMESPACE_PREFIX):
        device = _NT_DEVICE_PREFIX + device[len(_NT_NAMESPACE_PREFIX):]
    elif device.startswith(_WIN32_DEVICE_PREFIX):
        device = _NT_DEVICE_PREFIX + device[len(_WIN32_DEVICE_PREFIX):]
    elif device.startswith(_WIN32_FILE_PREFIX):
        device = device[len(_WIN32_FILE_PREFIX):]
    return device.rstrip("\\").lower()


def _dos_root(name):
    """Normalise a drive entry to the spelling QueryDosDeviceW wants."""
    drive = name.strip().rstrip("\\")
    if not drive:
        return None
    if drive.startswith(_UNC_PREFIX):
        # A network drive of this session; its device name is a redirector and
        # is handled by _REDIRECTORS.
        return None
    if drive.endswith(":"):
        return drive
    return drive + ":"


def device_map():
    """``[(device name, openable root), ...]``, longest device name first.

    Built once per process. A volume can carry several names
    (``\\Device\\HarddiskVolume3`` and ``\\Device\\VhdHardDisk{...}`` for the
    same disk); they all open through the same drive letter, so they are all
    recorded. Longest first keeps a nested volume from being shadowed by the
    disk device it sits on.
    """
    global _device_map
    if _device_map is not None:
        return _device_map

    entries = {}
    for drive in _logical_drives():
        root = _dos_root(drive)
        if root is None:
            continue
        targets = _device_targets(root)
        if not targets:
            continue
        openable = root.rstrip(":") + ":\\"
        for target in targets:
            device = _normalise_device(target)
            if device and device not in entries:
                entries[device] = openable

    _device_map = sorted(entries.items(), key=lambda item: len(item[0]), reverse=True)
    return _device_map


def _join(root, remainder):
    root = root.rstrip("\\")
    if not remainder:
        return root
    return root + "\\" + remainder.strip("\\")


def _translate_device_path(value):
    """``\\Device\\...`` or ``\\??\\...`` -> drive/UNC path, or ``None``."""
    if not value:
        return None
    if value.startswith(_NT_NAMESPACE_PREFIX):
        value = _NT_DEVICE_PREFIX + value[len(_NT_NAMESPACE_PREFIX):]
    elif value.startswith(_WIN32_DEVICE_PREFIX):
        value = _NT_DEVICE_PREFIX + value[len(_WIN32_DEVICE_PREFIX):]
    if not value.lower().startswith(_NT_DEVICE_PREFIX):
        return None

    lowered = value.lower()
    for redirector in _REDIRECTORS:
        if lowered.startswith(redirector):
            remainder = value[len(redirector):].strip("\\")
            if remainder:
                return _UNC_PREFIX + remainder
            return None

    for device, root in device_map():
        if lowered == device or lowered.startswith(device + "\\"):
            candidate = _join(root, value[len(device):])
            if _is_openable(candidate):
                return candidate
    return None


def _is_openable(candidate):
    """``True`` when ``candidate`` is a path a caller can hand to open()."""
    if not candidate:
        return False
    lowered = candidate.lower()
    for prefix in (_NT_DEVICE_PREFIX, _NT_NAMESPACE_PREFIX, _WIN32_DEVICE_PREFIX,
                   _WIN32_FILE_PREFIX):
        if lowered.startswith(prefix):
            return False
    if candidate.startswith(_UNC_PREFIX):
        return len(candidate) > len(_UNC_PREFIX)
    return len(candidate) > 2 and candidate[1] == ":"


def to_openable_path(value):
    """Return ``value`` as a DOS drive or UNC path, or ``None``.

    Accepts the spellings the Win32 naming APIs produce and never returns a
    device path, an extended length prefix, an empty string or a placeholder.
    """
    if not isinstance(value, str) or not value:
        return None
    candidate = value.strip()
    if not candidate:
        return None

    if candidate.startswith(_NT_NAMESPACE_PREFIX) or candidate.startswith(_NT_DEVICE_PREFIX):
        return _translate_device_path(candidate)
    if candidate.startswith(_WIN32_DEVICE_PREFIX):
        return _translate_device_path(candidate)

    if candidate.startswith(_WIN32_FILE_PREFIX):
        candidate = candidate[len(_WIN32_FILE_PREFIX):]
        if candidate.lower().startswith("unc\\"):
            # \\?\UNC\server\share\dir is the file namespace spelling of UNC.
            candidate = _UNC_PREFIX + candidate[len("unc\\"):].strip("\\")
        elif not _is_openable(candidate):
            # \\?\Volume{...}\... and friends are not something a caller can
            # open from a ticket; better no path than a misleading one.
            return None

    if not _is_openable(candidate):
        return None
    if candidate[1] == ":" and candidate[2:3] not in ("\\", "/"):
        candidate = candidate[:2] + "\\" + candidate[2:]
    return candidate


def mapped_file_name(handle, address):
    """The openable path of the file mapped at ``address``, or ``None``.

    ``None`` means the kernel named no file for that address -- an anonymous
    section, private memory, reserved memory -- or that the file it named
    cannot be turned into a path the caller could open.
    """
    if w.GetMappedFileNameW is None:
        return None
    buffer = _wide_buffer(PATH_BUFFER_CHARS)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        return None
    return to_openable_path(buffer.value)


def process_image_name(handle):
    """The openable path of the executable image of ``handle``'s process."""
    if w.QueryFullProcessImageNameW is None:
        return None
    size = ctypes.wintypes.DWORD(PATH_BUFFER_CHARS)
    buffer = _wide_buffer(PATH_BUFFER_CHARS)
    ok = w.QueryFullProcessImageNameW(handle, 0, buffer, ctypes.byref(size))
    if not ok:
        return None
    return to_openable_path(buffer.value)

